import React, { useEffect, useRef, useState } from "react";
import TicketsTable from "./TicketsTable";
import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import TicketFormModal from "./TicketFormModal";
import transportApi from "../../../api/transport/transportApi";
import employeesApi from "../../../api/employees/employeesApi";
import { ToastContainer, toast } from "react-toastify";
import moment from "moment";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import { Loading } from "../../../components";

const columns = [
  { name: "First Name", uid: "first_name" },
  { name: "Last Name", uid: "last_name" },
  { name: "Payment Method", uid: "payment_method_title" },
  { name: "Payment Ref", uid: "payment_reference" },
  { name: "Reference Number", uid: "reference_number" },
  { name: "Paid", uid: "is_paid" },
  // { name: "Narrative", uid: "payment_narrative" },
  { name: "Vehicle", uid: "vehicle_registration" },
  // { name: "Document Number", uid: "document_number" },
  // { name: "Fare", uid: "fare" },
  { name: "Owner", uid: "owner_title" },
  { name: "Amount", uid: "ticket_total_amount" },
  { name: "Date", uid: "created" },
  { name: "Destination", uid: "destination_title" },
  { name: "Origin", uid: "origin" },
  { name: "Actions", uid: "actions" },
];

function TicketsList() {
  const [openEditModal, setopenEditModal] = useState(false);

  const navigate = useNavigate();
  const [vehicle, setVehicle] = useState();
  const [vehicles, setVehicles] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const transportActionsApi = useApi(transportApi.transportAction);
  const employeesActionsApi = useApi(employeesApi.employeesActionAdmin);
  const [user, setUser] = useState();
  const [selectedDates, setSelectedDates] = useState();
  const [totalValue, settotalValue] = useState(0.0);
  const [totalCount, settotalCount] = useState(0);
  const [employees, setemployees] = useState([]);
  const [selectedEmployeeId, setselectedEmployeeId] = useState(null);
  const [errors, setErrors] = useState([]);

  const getEmployees = async () => {
    await employeesActionsApi.request({
      action: "RetrieveEntityEmployees",
    });
  };

  const getTickets = async () => {
    setdata([]);
    await transportActionsApi.request({
      action: "GetEntityTickets",
      from_date: moment().format("YYYY-MM-DD"),
      to_date: moment().format("YYYY-MM-DD"),
    });
  };

  const getEntityTicketsByDate = async () => {
    setdata([]);
    await transportActionsApi.request({
      action: "GetEntityTickets",
      from_date: selectedDates ? selectedDates[0] : "",
      to_date: selectedDates ? selectedDates[1] : "",
    });
  };

  const getUserTickets = async (selected) => {
    settotalValue(0.0);
    settotalCount(0);
    setdata([]);
    await transportActionsApi.request({
      action: "GetUserTicketsById",
      user: selected,
      from_date: moment().format("YYYY-MM-DD"),
      to_date: moment().format("YYYY-MM-DD"),
    });
  };

  const getValue = (data) => {
    console.log("data", data);
    let value = 0.0;
    data.map((x) => {
      value = value + parseFloat(x.ticket_total_amount);
    });

    // settotalValue(value.toFixed(2));
    return value.toFixed(2);
  };

  useEffect(() => {
    if (selectedDates) {
      getEntityTicketsByDate();
    }
  }, [selectedDates]);
  useEffect(() => {
    setdata(vehicles);
  }, [vehicles]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((error) => toast.error(error));
    }
  }, [errors]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      vehicles &&
      vehicles.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        vehicles.filter((x) =>
          x.passenger_phone.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(vehicles);
    }
  };

  useEffect(() => {
    if (selectedEmployeeId === null) {
      getTickets();
    }

  }, [selectedEmployeeId]);

  useEffect(() => {
    getEmployees();
  }, []);

  const handleEditAction = (item) => {
    setopenEditModal(true);
    setVehicle(item);
    setmodalTitle(`Edit ${item.tittle}`);
    setUpdated(false);
  };

  const handleAddAction = () => {
    setopenEditModal(true);
    setmodalTitle("Add new route");
    setVehicle(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/routes/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/routes/delete/${item.id}`);
  };

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.length) {
      setVehicles(transportActionsApi.data);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.errors &&
      transportActionsApi.data.errors.length
    ) {
      setErrors(transportActionsApi.data.errors);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 1
    ) {
      // toast.error(transportActionsApi.data.response_message);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 0
    ) {
      // toast.success(transportActionsApi.data.response_message);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    console.log("employeesActionsApi.data", employeesActionsApi.data);
    setemployees(employeesActionsApi.data);
  }, [employeesActionsApi.data]);

  useEffect(() => {
    if (vehicles && vehicles.length) {
      settotalValue(getValue(vehicles));
      settotalCount(vehicles.length);
    }
  }, [vehicles]);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      // getTickets(user);

      // Simulating an API failure in the polling callback
      //   const shouldFail = Math.random() < 0.2; // Simulate 20% chance of API failure

      //   if (shouldFail) {
      //     setIsPollingEnabled(false);
      //     console.log("Polling failed. Stopped polling.");
      //   }
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 5000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getTickets]);

  useEffect(() => {
    if (selectedEmployeeId !== null) {
      getUserTickets(selectedEmployeeId);
    }
  }, [selectedEmployeeId]);

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />

      {transportActionsApi && transportActionsApi.loading ? (
        <Loading loading={transportActionsApi.loading} />
      ) : (
        <p></p>
      )}

      {openEditModal && (
        <TicketFormModal
          openEditModal={openEditModal}
          setopenEditModal={setopenEditModal}
          item={vehicle}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <TicketsTable
        totalCount={totalCount}
        totalValue={totalValue}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
        selectedDates={selectedDates}
        setSelectedDates={setSelectedDates}
        employees={employees}
        selectedEmployeeId={selectedEmployeeId}
        setselectedEmployeeId={setselectedEmployeeId}
      />
    </div>
  );
}

export default TicketsList;
