import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { Loading } from '../../../components';
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";



export default function TicketFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();
    const [vehicle, setVehicle] = useState(item ? item : null)

    console.log("Item at modal", item)

    const [routes, setRoutes] = useState([])
    const getRoutesActionsApi = useApi(transportApi.transportAction)
    const transportActionsApi = useApi(transportApi.transportAction)
        const getRoutes = async () => {
            await getRoutesActionsApi.request({
                "action": "GetEntityRoutes"
    
            })
        }
    
        useEffect(() => {
            getRoutes()
        }, [])
    
        useEffect(() => {
    
            if (getRoutesActionsApi.data && getRoutesActionsApi.data.length) {
    
                setRoutes(getRoutesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
            }
    
            console.log
                ('getRoutesActionsApi.data', getRoutesActionsApi.data)
        }, [getRoutesActionsApi.data])

    const [errors, setErrors] = useState();
   
    
    
    
    
    const handleVehicleAction = async (data) => {
        console.log("data at",data
        )
        const result = await transportActionsApi.request(data);

        if (result.ok) {
            console.log("res", result)
            setUpdated(true)
            setopenEditModal(false)
        } else {
            setUpdated(false)
        }

    }

    useEffect(() => { }, [vehicle])

    useEffect(() => {

        if (transportActionsApi.data) {
            setopenEditModal(false)
            // if (transportActionsApi.data.destination) {
            //     setDestination(transportActionsApi.data.destination)
            // }

            if (transportActionsApi.data.errors) {
                setErrors(transportActionsApi.data.errors)
            }
        }



        console.log("transportActionsApi.data",transportActionsApi.data)
    }, [transportActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            route: vehicle ? {'label':vehicle.route_title, 'value':vehicle.route} : '',
            title: vehicle ? vehicle.title : '',
            seats: vehicle ? vehicle.seats : '',
            registration: vehicle ? vehicle.registration : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleVehicleAction({
                    "action": "UpdateVehicle",
                    "vehicle_details": {
                        "vehicle_id": vehicle.id,
                        "route_id": values.route.value,
                        "title": values.title,
                        "seats": values.seats,
                        "registration": values.registration ? values.registration : '',
                    }
                })
            } else {
                handleVehicleAction({
                    "action": "CreateVehicle",
                    "vehicle_details": {
                        "title": values.title,
                        "seats": values.seats,
                        "registration": values.registration ? values.registration : '',
                        "route_id": values.route.value,
                    }
                })
            }




            // resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {transportActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>

                                <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="route"
                                            key="route"
                                            name="route"
                                            components={animatedComponent}
                                            placeholder="Select route"
                                            isClearable
                                            value={formik.values.route}
                                            onChange={(value) => formik.setFieldValue("route", value)}
                                            options={routes}
                                        />
                                        {formik.touched.route && formik.errors.route ? (
                                            <p className="text-red-500 text-sm">{formik.errors.route}</p>
                                        ) : null}
                                    </div>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter vehicle title or nickname"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />
                                    <Input
                                        id="seats"
                                        name="seats"
                                        autoFocus
                                        label="Seats"
                                        placeholder="Enter number of seats"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.seats}
                                        value={formik.values.seats}
                                    />

                                    <Textarea
                                        id="registration"
                                        key="registration"
                                        name="registration"
                                        label="Registration number"
                                        placeholder="Type registration number"
                                        variant="bordered"
                                        defaultValue={formik.values.registration}
                                        value={formik.values.registration}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
